class IntelligentRouter:
    def __init__(self):
        self.model_performance = {}
        self.routing_weights = {}

    def route_task(self, task_type: str, content_length: int, complexity: str, sensitivity: str) -> str:
        if content_length > 100000:
            return "mamba-long-context"
        elif content_length > 50000:
            return "qwen-3-235b-a22b-thinking-2507"
        elif task_type == "planning":
            return "grok-4-fast"
        elif task_type == "critique":
            return "claude-sonnet-4.5"
        elif task_type == "synthesis":
            return "gpt-oss-120b"
        elif task_type == "analysis":
            return "qwen-3-235b-a22b-thinking-2507"
        elif complexity == "high":
            return "qwen-3-235b-a22b-thinking-2507"
        else:
            return "gpt-oss-120b"

    def update_routing_weights(self, task_features: Dict, model: str, quality_score: float):
        key = f"{task_features.get('type', '')}_{model}"
        if key not in self.model_performance:
            self.model_performance[key] = []
        self.model_performance[key].append(quality_score)
        if len(self.model_performance[key]) > 100:
            self.model_performance[key] = self.model_performance[key][-100:]

class VectorMemory:
    def __init__(self):
        self.index = None
        self.embedding_model = None
        try:
            self.pinecone_client = Pinecone(api_key=os.getenv('PINECONE_API_KEY'))
            self.embedding_model = SentenceTransformer('all-MiniLM-L6-v2')
            try:
                self.index = self.pinecone_client.Index('cognitive-memory')
                logger.info("Pinecone vector memory initialized successfully")
            except Exception as e:
                logger.warning(f"Pinecone index not found, attempting to create: {e}")
                pinecone_region = os.getenv('PINECONE_REGION', 'us-east-1')
                self.pinecone_client.create_index(
                    name='cognitive-memory',
                    dimension=384,
                    metric='cosine',
                    spec=ServerlessSpec(cloud='aws', region=pinecone_region)
                )
                time.sleep(60)
                self.index = self.pinecone_client.Index('cognitive-memory')
                logger.info("Pinecone index created successfully")
        except Exception as e:
            logger.warning(f"Pinecone initialization failed: {e} - Vector memory disabled")

    def store_insight(self, content: str, metadata: Dict):
        if not self.index or not self.embedding_model:
            logger.debug("Vector memory not available - skipping insight storage")
            return None
        try:
            vector_id = hashlib.sha256(f"{content}{time.time()}".encode()).hexdigest()
            embedding = self.embedding_model.encode(content).tolist()
            self.index.upsert(vectors=[{
                'id': vector_id,
                'values': embedding,
                'metadata': {
                    **metadata,
                    'content': content[:1000],
                    'timestamp': time.time()
                }
            }])
            return vector_id
        except Exception as e:
            logger.error(f"Failed to store insight: {e}")
            return None

    def recall_similar(self, query: str, top_k: int = 20) -> List[Dict]:
        if not self.index or not self.embedding_model:
            logger.debug("Vector memory not available - returning empty memories")
            return []
        try:
            query_embedding = self.embedding_model.encode(query).tolist()
            results = self.index.query(vector=query_embedding, top_k=top_k, include_metadata=True)
            recalled = []
            for match in results.matches:
                recalled.append({
                    'content': match.metadata.get('content', ''),
                    'score': match.score,
                    'metadata': match.metadata
                })
            return recalled
        except Exception as e:
            logger.error(f"Pinecone recall_similar failed: {e}")
            return []

class DocumentProcessor:
    def __init__(self, cerebras_client: Cerebras, xai_client: OpenAI):
        self.cerebras = cerebras_client
        self.xai = xai_client
        self.router = IntelligentRouter()

    def process_large_document(self, document: str, query: str) -> Dict:
        doc_length = len(document)

        model = self.router.route_task("document_processing", doc_length, "high", "medium")

        chunks = self._intelligent_chunking(document, doc_length)

        chunk_analyses = []
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = [executor.submit(self._analyze_chunk, chunk, query, model) for chunk in chunks]
            for future in as_completed(futures):
                chunk_analyses.append(future.result())

        full_synthesis = self._synthesize_chunks(chunk_analyses, query)

        return {
            'document_length': doc_length,
            'chunks_processed': len(chunks),
            'model_used': model,
            'chunk_analyses': chunk_analyses,
            'full_synthesis': full_synthesis
        }

    def _intelligent_chunking(self, document: str, doc_length: int) -> List[str]:
        if doc_length < 50000:
            return [document]

        chunk_size = 40000
        overlap = 5000
        chunks = []
        start = 0

        while start < doc_length:
            end = min(start + chunk_size, doc_length)
            chunks.append(document[start:end])
            start += chunk_size - overlap

        return chunks

    def _analyze_chunk(self, chunk: str, query: str, model: str) -> Dict:
        analysis_prompt = f"""Analyze this document section in relation to the query.

Query: {query}

Document section:
{chunk[:30000]}

Provide comprehensive analysis focusing on relevance to the query."""

        try:
            if model == "qwen-3-235b-a22b-thinking-2507":
                response = self.cerebras.chat.completions.create(
                    model="qwen-3-235b-a22b-thinking-2507",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=32768,
                    temperature=0.7
                )
                return {'analysis': response.choices[0].message.content, 'model': model}
            elif model == "grok-4-fast":
                response = self.xai.chat.completions.create(
                    model="grok-4-fast",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=32768,
                    temperature=0.7
                )
                return {'analysis': response.choices[0].message.content, 'model': model}
            else:
                response = self.cerebras.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=32768,
                    temperature=0.7
                )
                return {'analysis': response.choices[0].message.content, 'model': model}
        except Exception as e:
            return {'error': str(e), 'model': model}

    def _synthesize_chunks(self, chunk_analyses: List[Dict], query: str) -> str:
        all_analyses = "\n\n".join([f"Analysis {i+1}:\n{a.get('analysis', '')[:5000]}" for i, a in enumerate(chunk_analyses)])

        synthesis_prompt = f"""Synthesize all chunk analyses into a coherent comprehensive response.

Query: {query}

Chunk analyses:
{all_analyses[:50000]}

Provide a unified, comprehensive synthesis that addresses the query."""

        try:
            response = self.cerebras.chat.completions.create(
                model="qwen-3-235b-a22b-thinking-2507",
                messages=[{"role": "user", "content": synthesis_prompt}],
                max_tokens=32768,
                temperature=0.7
            )
            return response.choices[0].message.content
        except Exception as e:
            return f"Synthesis error: {str(e)}"

