class EnhancedExaSearchEngine:
    def __init__(self, exa: Exa):
        self.exa = exa

    def enhanced_neural_search(self, query: str, max_results: int = 100) -> List[Dict]:
        all_results = []
        seen_urls = set()

        try:
            neural_result = self.exa.search_and_contents(
                query=query,
                type="neural",
                use_autoprompt=True,
                num_results=max_results,
                text=True,
                highlights={"num_sentences": 5, "highlights_per_url": 3},
                livecrawl="preferred"
            )

            for r in neural_result.results:
                if r.url not in seen_urls:
                    seen_urls.add(r.url)
                    all_results.append({
                        'url': r.url,
                        'title': getattr(r, 'title', ''),
                        'text': getattr(r, 'text', ''),
                        'highlights': getattr(r, 'highlights', []),
                        'published_date': getattr(r, 'published_date', None),
                        'author': getattr(r, 'author', None),
                        'search_type': 'neural'
                    })
        except Exception as e:
            logger.error(f"Enhanced neural search failed: {e}")

        return all_results

    def deep_subpage_discovery(self, urls: List[str], max_per_url: int = 10) -> List[Dict]:
        all_content = []

        def process_url(url: str):
            try:
                result = self.exa.get_contents(
                    ids=[url],
                    text=True,
                    highlights=True,
                    livecrawl="always",
                    subpages=max_per_url,
                    subpage_target=["docs", "documentation", "article", "research", "paper", "guide", "news", "blog", "analysis", "report", "study", "whitepaper"]
                )

                return [{
                    'url': r.url if hasattr(r, 'url') else url,
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'type': 'subpage_discovery'
                } for r in result.results]
            except Exception as e:
                logger.debug(f"Subpage discovery failed for {url}: {e}")
                return []

        with ThreadPoolExecutor(max_workers=20) as executor:
            futures = [executor.submit(process_url, url) for url in urls[:50]]
            for future in as_completed(futures):
                all_content.extend(future.result())

        return all_content

    def find_similar_content_batch(self, urls: List[str], num_per_url: int = 100) -> List[Dict]:
        all_similar = []

        def find_similar(url: str):
            try:
                result = self.exa.find_similar_and_contents(
                    url=url,
                    num_results=num_per_url,
                    text=True,
                    highlights=True,
                    exclude_source_domain=True
                )

                return [{
                    'url': r.url,
                    'title': getattr(r, 'title', ''),
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'type': 'similar_content'
                } for r in result.results]
            except Exception as e:
                logger.debug(f"Find similar failed for {url}: {e}")
                return []

        with ThreadPoolExecutor(max_workers=20) as executor:
            futures = [executor.submit(find_similar, url) for url in urls[:30]]
            for future in as_completed(futures):
                all_similar.extend(future.result())

        return all_similar

    def multi_type_search(self, query: str, num_results: int = 100) -> List[Dict]:
        all_results = []
        seen_urls = set()

        search_types = ['neural', 'keyword', 'auto']

        with ThreadPoolExecutor(max_workers=3) as executor:
            futures = []
            for search_type in search_types:
                futures.append(executor.submit(self._single_type_search, query, search_type, num_results))

            for future in as_completed(futures):
                results = future.result()
                for r in results:
                    if r['url'] not in seen_urls:
                        seen_urls.add(r['url'])
                        all_results.append(r)

        return all_results

    def _single_type_search(self, query: str, search_type: str, num_results: int) -> List[Dict]:
        try:
            result = self.exa.search_and_contents(
                query=query,
                type=search_type,
                num_results=num_results,
                text=True,
                highlights=True,
                livecrawl="preferred"
            )

            return [{
                'url': r.url,
                'title': getattr(r, 'title', ''),
                'text': getattr(r, 'text', ''),
                'highlights': getattr(r, 'highlights', []),
                'published_date': getattr(r, 'published_date', None),
                'author': getattr(r, 'author', None),
                'search_type': search_type
            } for r in result.results]
        except Exception as e:
            logger.error(f"Search type {search_type} failed: {e}")
            return []

