    def coordinate_research(self, query: str, plan: Dict) -> Dict:
        librarian_results = []

        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = []
            for strategy in plan.get('search_strategies', [])[:5]:
                search_query = strategy.get('strategy', query)
                futures.append(executor.submit(self.librarian_agent, search_query, {}))

            for future in as_completed(futures):
                result = future.result()
                librarian_results.extend(result.get('results', []))

        all_sources = []
        seen_urls = set()
