    def dynamic_search_execution(self, plan: Dict, iteration: int) -> Dict:
        self.update_state(
            current_action=f'Executing adaptive search strategies (iteration {iteration})',
            current_phase='Search Execution',
            progress=10 + (iteration * 8)
        )

        strategies = plan.get('search_strategies', [])
        strategies.sort(key=lambda x: x.get('priority', 0), reverse=True)

        all_results = []
        strategy_performance = []

        with ThreadPoolExecutor(max_workers=15) as executor:
            futures = []
            for strategy in strategies[:8]:
                search_query = strategy.get('strategy', '')
                for search_type in ['neural', 'keyword', 'auto']:
                    futures.append(executor.submit(
                        self._execute_single_search,
                        search_query,
                        search_type,
                        strategy
                    ))

            for future in as_completed(futures):
                result = future.result()
                all_results.extend(result['results'])
                strategy_performance.append(result['performance'])

        unique_sources = {}
        for result in all_results:
            url = result.get('url', '')
            if url and url not in unique_sources:
                unique_sources[url] = result

        return {
            'sources': list(unique_sources.values()),
            'performance': strategy_performance,
            'total_found': len(unique_sources)
        }

    def _execute_single_search(self, query: str, search_type: str, strategy: Dict) -> Dict:
        start_time = time.time()

        try:
            result = self.exa.search_and_contents(
                query=query,
                type=search_type,
                num_results=100,
                text=True,
                highlights=True,
                livecrawl="preferred",
                use_autoprompt=True
            )

            sources = [{
                'url': r.url,
                'title': getattr(r, 'title', ''),
                'text': getattr(r, 'text', ''),
                'highlights': getattr(r, 'highlights', []),
                'published_date': getattr(r, 'published_date', None),
                'author': getattr(r, 'author', None),
                'search_type': search_type,
                'strategy': strategy.get('strategy', '')
            } for r in result.results]

            elapsed = time.time() - start_time

            return {
                'results': sources,
                'performance': {
                    'query': query,
                    'type': search_type,
                    'count': len(sources),
                    'time': elapsed,
                    'strategy': strategy.get('strategy', '')
                }
            }
        except Exception as e:
            return {
                'results': [],
                'performance': {
                    'query': query,
                    'type': search_type,
                    'count': 0,
                    'time': time.time() - start_time,
                    'error': str(e)
                }
            }

