@app.route('/api/stream/<session_id>', methods=['GET'])
def stream_status(session_id):
    def generate():
        msg_queue = queue.Queue(maxsize=100)

        with agent.state_lock:
            if session_id not in agent.session_subscribers:
                agent.session_subscribers[session_id] = []
            agent.session_subscribers[session_id].append(msg_queue)

        try:
            current_state = agent.get_state(session_id)
            if current_state:
                yield f"data: {json.dumps(current_state, default=str)}\n\n"

            timeout_counter = 0
            while timeout_counter < 2000:
                try:
                    message = msg_queue.get(timeout=1)
                    yield f"data: {message}\n\n"

                    try:
                        data = json.loads(message)
                        if data.get('status') in ['completed', 'error']:
                            break
                    except:
                        pass

                    timeout_counter = 0
                except queue.Empty:
                    timeout_counter += 1
                    yield f": keepalive\n\n"
        finally:
            with agent.state_lock:
                if session_id in agent.session_subscribers:
                    try:
                        agent.session_subscribers[session_id].remove(msg_queue)
                    except:
                        pass

    return Response(generate(), mimetype='text/event-stream')

